ch(1,"ईंटें, मनके तथा अस्थियाँ: हड़प्पा सभ्यता","Bricks, Beads and Bones: The Harappan Civilisation","आज से भारतीय इतिहास के कुछ विषय। पहला अध्याय, हड़प्पा सभ्यता, लगभग 4500 वर्ष पुरानी।",[
 ("L","🏺","हड़प्पा सभ्यता",["काल: लगभग 2600–1900 ई.पू. (विकसित हड़प्पा)","खोज: 1921 हड़प्पा (दयाराम साहनी), 1922 मोहनजोदड़ो (राखालदास बनर्जी)","अन्य स्थल: लोथल (बंदरगाह), कालीबंगा, धौलावीरा, राखीगढ़ी","कांस्य युगीन · लिपि अभी तक पढ़ी नहीं गई"],"हड़प्पा सभ्यता, लगभग छब्बीस सौ से उन्नीस सौ ईसा पूर्व। उन्नीस सौ इक्कीस में दयाराम साहनी ने हड़प्पा, और उन्नीस सौ बाईस में राखालदास बनर्जी ने मोहनजोदड़ो खोजा। लोथल एक बंदरगाह था। इनकी लिपि आज तक पढ़ी नहीं जा सकी।"),
 ("L","🏙️","नगर नियोजन",["दुर्ग (ऊँचा) और निचला शहर","सड़कें ग्रिड पद्धति में, समकोण पर काटतीं","पक्की ईंटें — मानक अनुपात 1:2:4","ढकी हुई नालियाँ — उत्कृष्ट जल निकासी","महान स्नानागार (मोहनजोदड़ो), अन्नागार"],"हड़प्पा का नगर नियोजन अद्भुत था। शहर दो भागों में, ऊँचा दुर्ग, और निचला शहर। सड़कें एक-दूसरे को समकोण पर काटती थीं। पक्की ईंटें एक निश्चित अनुपात की। ढकी हुई नालियाँ, ऐसी जल निकासी व्यवस्था उस समय कहीं नहीं थी। मोहनजोदड़ो का महान स्नानागार प्रसिद्ध है।"),
 ("L","🐂","अर्थव्यवस्था और पतन",["कृषि: गेहूँ, जौ, कपास (सबसे पहले) · हल (बनावली)","शिल्प: मनके (चन्हुदड़ो), मुहरें (पशुपति), बाट","व्यापार: मेसोपोटामिया ('मेलुहा')","पतन के कारण: जलवायु परिवर्तन, बाढ़, नदी मार्ग बदलना, वनोन्मूलन","अलेक्ज़ेंडर कनिंघम: ASI के पहले महानिदेशक · जॉन मार्शल"],"लोग गेहूँ, जौ, और कपास उगाते थे, कपास उगाने वाले वो दुनिया में पहले थे। मनके, मुहरें, और बाट बनाते थे। मेसोपोटामिया से व्यापार होता था, जो उन्हें मेलुहा कहते थे। उन्नीस सौ ईसा पूर्व के आसपास, शायद जलवायु बदलने और बाढ़ से, ये सभ्यता धीरे-धीरे समाप्त हुई।")],
 ("मोहनजोदड़ो की खोज किसने की?","राखालदास बनर्जी (1922)","मोहनजोदड़ो की खोज किसने की?","राखालदास बनर्जी ने।"),("हड़प्पा का बंदरगाह?","लोथल","हड़प्पा सभ्यता का प्रसिद्ध बंदरगाह?","लोथल।"),"राजा, किसान और नगर")
